// Circuit Breaker — simplified implementation
class CircuitBreaker {
  constructor(fn, { threshold = 5, timeout = 10000 } = {}) {
    this.fn = fn;
    this.threshold = threshold; // failures before opening
    this.timeout = timeout;     // ms before half-open probe
    this.failures = 0;
    this.state = 'CLOSED';      // CLOSED | OPEN | HALF_OPEN
    this.nextAttempt = Date.now();
  }

  async call(...args) {
    if (this.state === 'OPEN') {
      if (Date.now() < this.nextAttempt) {
        throw new Error('Circuit OPEN — fast fail');
      }
      this.state = 'HALF_OPEN';
    }
    try {
      const result = await this.fn(...args);
      this.onSuccess();
      return result;
    } catch (err) {
      this.onFailure();
      throw err;
    }
  }

  onSuccess() {
    this.failures = 0;
    this.state = 'CLOSED';
  }

  onFailure() {
    this.failures++;
    if (this.failures >= this.threshold) {
      this.state = 'OPEN';
      this.nextAttempt = Date.now() + this.timeout;
    }
  }
}

// Usage
const paymentBreaker = new CircuitBreaker(callPaymentService, { threshold: 3 });
try {
  const result = await paymentBreaker.call({ amount: 99 });
} catch (e) {
  // Fall back gracefully — queue for retry, return cached result, etc.
  console.warn('Payment unavailable, falling back:', e.message);
}

// CQRS + Event Sourcing — conceptual model

// --- WRITE side: append events, never overwrite ---
async function placeOrder(orderId, items, userId) {
  const event = {
    type: 'OrderPlaced',
    orderId,
    items,
    userId,
    occurredAt: new Date().toISOString(),
  };
  await eventStore.append('orders', orderId, event); // immutable append
  await eventBus.publish(event);                     // notify read-side projectors
}

// --- READ side: materialized view, rebuilt from events ---
async function rebuildOrderView(orderId) {
  const events = await eventStore.load('orders', orderId);
  return events.reduce((state, event) => {
    switch (event.type) {
      case 'OrderPlaced':   return { ...state, status: 'placed', items: event.items };
      case 'OrderShipped':  return { ...state, status: 'shipped', trackingId: event.trackingId };
      case 'OrderCancelled': return { ...state, status: 'cancelled' };
      default: return state;
    }
  }, {});
}
// The read model can be a Redis cache or a denormalized Postgres table —
// optimized for query patterns without affecting the write model.
